input.command:
sed -n 319p docs/registry/architecture.yaml | cut -c1-200; cat > /tmp/chk.py <<'EOF'
import yaml,re,sys
L=open('docs/registry/architecture.yaml',encoding='utf-8').read().split("\n")
for i,l in enumerate(L):
    m=re.match(r"^\s+(?:- )?\w+: (.*)$",l)
    if m:
        v=m.group(1)
        if v and v[0] not in "\"'[{|>&*!" :
            v2=v.split(" #")[0]
            if ": " in v2: print(i+1,l[:150])
EOF
python /tmp/chk.py

